<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor: <strong><?= V::escape($row['reservation_ref']) ?></strong></p><p>Tanggal: <?= V::escape($row['reservation_date']) ?> · Cabang: <?= V::escape($row['branch_code'].' - '.$row['branch_name']) ?> · Gudang: <?= V::escape($row['warehouse_code'].' - '.$row['warehouse_name']) ?></p><p>Status: <strong><?= V::escape($row['status']) ?></strong></p><p>Kebutuhan: <?= V::escape((string)$row['need_ref']) ?> <?= V::escape((string)$row['need_type']) ?></p><?php if($row['status']==='DRAFT'&&$access->can('inventory.reservation.reserve')): ?><form method="post" action="<?= $this->url('/inventory/reservation-transition') ?>" onsubmit="return confirm('Kunci reservasi stok?')"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="reserve"><button class="button button-primary">Reservasi</button></form><?php if($access->can('inventory.reservation.cancel')): ?><form method="post" action="<?= $this->url('/inventory/reservation-transition') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="cancel"><button class="button">Batalkan</button></form><?php endif; ?><?php elseif($row['status']==='RESERVED'&&$access->can('inventory.reservation.release')): ?><form method="post" action="<?= $this->url('/inventory/reservation-transition') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="release"><button class="button">Lepas Reservasi</button></form><?php endif; ?></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Satuan</th><th>Diminta</th><th>Dicadangkan</th><th>Terpenuhi</th><th>Sisa</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['item_code'].' - '.$l['item_name']) ?></td><td><?= V::escape($l['unit_name']) ?></td><td><?= number_format((float)$l['quantity_requested'],3,',','.') ?></td><td><?= number_format((float)$l['quantity_reserved'],3,',','.') ?></td><td><?= number_format((float)$l['quantity_fulfilled'],3,',','.') ?></td><td><?= number_format((float)$l['quantity_reserved']-(float)$l['quantity_fulfilled'],3,',','.') ?></td></tr><?php endforeach ?></tbody></table></div></section><a class="button" href="<?= $this->url('/inventory/reservations') ?>">Kembali</a>
